import json, os

CKPT = "run_r551.json"
batches = list(range(1, 25))            # 24 batches of 50 records

def load():
    return json.load(open(CKPT)) if os.path.exists(CKPT) else {"done": []}

def run_agent(crash_at=None, max_turns=100):
    state, turns = load(), 0
    for b in batches:
        if b in state["done"]:
            continue                     # finished before the crash: skip
        if b == crash_at:
            raise RuntimeError(f"connection lost at batch {b}")
        state["done"].append(b)          # the real work would happen here
        json.dump(state, open(CKPT, "w"))   # checkpoint after every step
        turns += 1
        if turns >= max_turns:
            break                        # safety cap
    return turns

try:
    run_agent(crash_at=17)
except RuntimeError as e:
    print(e)
print("resumed and ran", run_agent(), "batches")
os.remove(CKPT)
# Output:
# connection lost at batch 17
# resumed and ran 8 batches

import time, functools

SPANS = []
PRICE_PER_M = {"input": 3.00, "output": 15.00}   # example prices, check current rates

def traced(name):
    def wrap(fn):
        @functools.wraps(fn)
        def inner(*a, **kw):
            start = time.perf_counter()
            result = fn(*a, **kw)
            span = {"name": name, "ms": round((time.perf_counter() - start) * 1000)}
            if isinstance(result, dict) and "in_tok" in result:
                span["tokens"] = result["in_tok"] + result["out_tok"]
                span["cost_usd"] = round(result["in_tok"] / 1e6 * PRICE_PER_M["input"]
                                         + result["out_tok"] / 1e6 * PRICE_PER_M["output"], 5)
            SPANS.append(span)
            return result
        return inner
    return wrap

@traced("chat MODEL")
def call_model(prompt):
    time.sleep(0.05)                    # stand-in for a real API call
    return {"text": "Rates are fixed for 5 years.", "in_tok": 1840, "out_tok": 212}

@traced("tool lookup_rate")
def lookup_rate():
    time.sleep(0.12)
    return 4.1

call_model("What is the fixed rate?"); lookup_rate()
for s in SPANS:
    print(s["name"], "| about", round(s["ms"], -1), "ms |", s.get("cost_usd", "-"))
# Output:
# chat MODEL | about 50 ms | 0.0087
# tool lookup_rate | about 120 ms | -
